application.css:
* { box-sizing: border-box; }

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #202b3c;
  background: #eef3f8;
}

body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(circle at 15% 10%, #dcecff 0, transparent 34%), linear-gradient(135deg, #f5f8fc 0%, #e8eff7 100%);
}

.app-shell { width: min(100% - 32px, 650px); margin: 0 auto; padding: 8vh 0 30px; }
.todo-card { background: rgba(255,255,255,.94); border: 1px solid rgba(210,222,237,.9); border-radius: 24px; padding: clamp(24px, 5vw, 44px); box-shadow: 0 22px 55px rgba(42,68,105,.12); }
.app-header { display: flex; align-items: center; gap: 15px; margin-bottom: 34px; }
.brand-mark { width: 46px; height: 46px; display: grid; place-items: center; color: white; font-size: 27px; font-weight: 800; border-radius: 14px; background: linear-gradient(145deg, #557ce8, #7656d8); box-shadow: 0 8px 17px rgba(91,103,217,.28); }
.eyebrow { margin: 0 0 4px; color: #71809a; font-size: 10px; font-weight: 800; letter-spacing: .16em; }
h1, h2 { margin: 0; }
h1 { color: #1d2940; font-size: clamp(26px, 5vw, 34px); letter-spacing: -.04em; }
.task-form { display: flex; gap: 10px; margin-bottom: 38px; }
.task-form input { min-width: 0; flex: 1; border: 1px solid #d9e1ec; border-radius: 12px; outline: none; padding: 14px 16px; color: #26344a; font: inherit; background: #f8fafc; transition: .2s; }
.task-form input:focus { border-color: #6b76e4; box-shadow: 0 0 0 4px rgba(107,118,228,.12); background: white; }
.task-form button { border: 0; border-radius: 12px; padding: 0 17px; color: white; background: #556bd9; font: inherit; font-weight: 700; cursor: pointer; transition: .2s; }
.task-form button:hover { background: #465bc5; transform: translateY(-1px); }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
h2 { font-size: 17px; letter-spacing: -.01em; }
.count-pill { border-radius: 20px; padding: 6px 10px; color: #5362bf; background: #eef0ff; font-size: 12px; font-weight: 700; }
.task-list { display: grid; gap: 10px; }
.task-item { display: flex; align-items: center; gap: 12px; min-height: 58px; padding: 10px 12px; border: 1px solid #e5eaf1; border-radius: 13px; background: #fff; transition: .2s; }
.task-item:hover { border-color: #ccd5e6; box-shadow: 0 5px 13px rgba(46,66,99,.06); }
.complete-control { flex: 0 0 24px; width: 24px; height: 24px; border: 2px solid #c7d1df; border-radius: 50%; color: white; background: transparent; cursor: pointer; display: grid; place-items: center; font-size: 14px; line-height: 1; }
.task-item[data-completed="true"] .complete-control { border-color: #65b99b; background: #65b99b; }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 15px; }
.task-item[data-completed="true"] .task-text { color: #9aa5b5; text-decoration: line-through; }
.delete-control { border: 0; padding: 7px; color: #aab5c4; background: transparent; font-size: 20px; line-height: 1; cursor: pointer; }
.delete-control:hover { color: #e06c79; }
.empty-state { margin: 24px 0 4px; color: #8a97a9; text-align: center; font-size: 14px; }
.footer-note { margin: 20px 0; color: #8b99ab; text-align: center; font-size: 12px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 480px) { .app-shell { width: min(100% - 20px, 650px); padding-top: 28px; } .task-form { flex-direction: column; } .task-form button { min-height: 46px; } }

application.javascript:
(() => {
  const form = document.getElementById('task-form');
  const input = document.querySelector('[data-testid="task-input"]');
  const list = document.querySelector('[data-testid="task-list"]');
  const emptyState = document.getElementById('empty-state');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const countLabel = document.getElementById('count-label');
  let tasks = [];

  function render() {
    list.innerHTML = '';
    tasks.forEach(task => {
      const item = document.createElement('article');
      item.className = 'task-item';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const complete = document.createElement('button');
      complete.type = 'button';
      complete.className = 'complete-control';
      complete.dataset.testid = 'task-complete';
      complete.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      complete.setAttribute('aria-pressed', String(task.completed));
      complete.textContent = task.completed ? '✓' : '';
      complete.addEventListener('click', () => {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete-control';
      remove.dataset.testid = 'task-delete';
      remove.setAttribute('aria-label', 'Delete task');
      remove.textContent = '×';
      remove.addEventListener('click', () => {
        tasks = tasks.filter(current => current.id !== task.id);
        render();
      });

      item.append(complete, text, remove);
      list.appendChild(item);
    });

    const remaining = tasks.filter(task => !task.completed).length;
    count.textContent = remaining;
    countLabel.textContent = remaining === 1 ? 'remaining' : 'remaining';
    emptyState.hidden = tasks.length !== 0;
  }

  form.addEventListener('submit', event => {
    event.preventDefault();
    const text = input.value.trim();
    if (!text) {
      input.focus();
      return;
    }
    tasks.push({ id: Date.now() + Math.random(), text, completed: false });
    input.value = '';
    render();
    input.focus();
  });

  render();
})();
